.modal-title {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.modal-body {
  padding: 4px 24px 20px;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.modal-body strong { color: var(--text); font-weight: 600; }

