  --text: #0f172a;
  --text-muted: #5b6573;
  --primary: #2f5bea;
  --primary-hover: #2548c4;
  --danger: #c92a2a;
  --danger-hover: #a61f1f;
  --danger-soft: #fdecec;
  --focus: #1d4ed8;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06), 0 1px 3px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 20px 40px -12px rgba(15, 23, 42, 0.25), 0 8px 16px -8px rgba(15, 23, 42, 0.15);
  --radius: 12px;
  --radius-sm: 8px;
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
  min-height: 100vh;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 8px;
  padding: 8px 12px;
  background: var(--text);
  color: #fff;
  border-radius: var(--radius-sm);
  text-decoration: none;
  z-index: 1000;
}
.skip-link:focus { top: 8px; }

.app-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 16px 24px;
}
.app-header-inner {
  max-width: 960px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.brand {
  font-weight: 700;
  letter-spacing: -0.01em;
  font-size: 1.05rem;
}
.brand-mark {
  display: inline-block;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  background: linear-gradient(135deg, #2f5bea, #7c3aed);
  vertical-align: middle;
  margin-right: 8px;
}

main { max-width: 960px; margin: 0 auto; padding: 32px 24px 64px; }

.preview-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.preview-figure { margin: 0; }
.preview-image-wrap {
  background: var(--surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 16 / 10;
  overflow: hidden;
}
.preview-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.preview-meta {
  padding: 20px 24px 8px;
}
.preview-title {
  margin: 0 0 4px;
  font-size: 1.5rem;
  letter-spacing: -0.01em;
}
.preview-sub {
  color: var(--text-muted);
  font-size: 0.925rem;
  margin: 0;
}

.preview-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 16px 24px 24px;
  border-top: 1px solid var(--border);
  margin-top: 16px;
}

.btn {
  appearance: none;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text);
  font: inherit;
  font-weight: 500;
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background-color .15s ease, border-color .15s ease, color .15s ease, box-shadow .15s ease;
  min-height: 40px;
}
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.btn .icon {
  width: 18px;
  height: 18px;
  flex: none;
}

.btn-secondary {
  background: var(--surface);
  border-color: var(--border);
  color: var(--text);
}
.btn-secondary:hover { background: var(--surface-2); }

.btn-primary {
  background: var(--primary);
  color: #fff;
}
.btn-primary:hover { background: var(--primary-hover); }

.btn-danger {
  background: var(--danger);
  color: #fff;
}
.btn-danger:hover { background: var(--danger-hover); }

.btn-danger-outline {
  background: var(--surface);
  color: var(--danger);
  border-color: var(--border);
}
.btn-danger-outline:hover {
  background: var(--danger-soft);
  border-color: var(--danger);
}

.spacer { flex: 1; }

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 100;
  animation: fade-in .15s ease-out;
}

.modal {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow-lg);
  width: 100%;
  max-width: 440px;
  border: 1px solid var(--border);
  animation: pop-in .18s ease-out;
  display: flex;
  flex-direction: column;
}

.modal-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 20px 24px 8px;
}
.modal-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--danger-soft);
  color: var(--danger);
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
}
.modal-icon svg { width: 22px; height: 22px; }

.modal-title {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.modal-body {
  padding: 4px 24px 20px;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.modal-body strong { color: var(--text); font-weight: 600; }

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 20px 20px;
  border-top: 1px solid var(--border);
  background: var(--surface);
  border-bottom-left-radius: var(--radius);
  border-bottom-right-radius: var(--radius);
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@keyframes fade-in { from { opacity: 0 } to { opacity: 1 } }
@keyframes pop-in {
  from { opacity: 0; transform: translateY(8px) scale(.98) }
  to   { opacity: 1; transform: translateY(0) scale(1) }
}

@media (prefers-reduced-motion: reduce) {
  .modal-backdrop, .modal { animation: none; }
  .btn { transition: none; }
}

@media (forced-colors: active) {
  .btn { border-color: ButtonBorder; }
  .modal { border: 1px solid CanvasText; }
  .modal-icon { border: 1px solid CanvasText; }
  .btn:focus-visible { outline-color: Highlight; }
}

@media (max-width: 520px) {
  .preview-actions { flex-direction: column; align-items: stretch; }
  .preview-actions .btn { justify-content: center; }
  .spacer { display: none; }
  .modal-footer { flex-direction: column-reverse; }
  .modal-footer .btn { width: 100%; justify-content: center; }
}
